package com.retro.launcher;
import android.graphics.*;
final class SoundGlyph {
 static void draw(Canvas c,float x,float y,float size,int mode){Paint b=new Paint();float u=size/16;int color=mode==2?0xff77efb3:mode==1?0xffffd76a:0xffb4dfff;b.setColor(color);String[] speaker={"0000000100000000","0000001100000000","0000011100000000","0011111100000000","0011111100000000","0011111100000000","0011111100000000","0011111100000000","0011111100000000","0011111100000000","0000011100000000","0000001100000000","0000000100000000"};if(mode==1){for(int yy=3;yy<13;yy++)for(int xx=5;xx<11;xx++)if(yy==3||yy==12||xx==5||xx==10)c.drawRect(x+xx*u,y+yy*u,x+(xx+1)*u,y+(yy+1)*u,b);for(int yy=4;yy<12;yy++){int xx=yy%4<2?2:3;c.drawRect(x+xx*u,y+yy*u,x+(xx+1)*u,y+(yy+1)*u,b);c.drawRect(x+(15-xx)*u,y+yy*u,x+(16-xx)*u,y+(yy+1)*u,b);}return;}for(int yy=0;yy<speaker.length;yy++)for(int xx=0;xx<16;xx++)if(speaker[yy].charAt(xx)=='1')c.drawRect(x+xx*u,y+(yy+1)*u,x+(xx+1)*u,y+(yy+2)*u,b);if(mode==2){for(int yy=4;yy<=11;yy++){int xx=yy<6||yy>9?12:14;c.drawRect(x+xx*u,y+yy*u,x+(xx+1)*u,y+(yy+1)*u,b);}c.drawRect(x+10*u,y+6*u,x+11*u,y+10*u,b);}else{b.setColor(0xffff7d89);for(int k=0;k<5;k++){c.drawRect(x+(10+k)*u,y+(6+k)*u,x+(11+k)*u,y+(7+k)*u,b);c.drawRect(x+(14-k)*u,y+(6+k)*u,x+(15-k)*u,y+(7+k)*u,b);}}}
}
